        bytes32 ownerSlot = bytes32(uint256(3));
        bytes32 newOwner = bytes32(uint256(uint160(attacker)));
        vm.store(TARGET, ownerSlot, newOwner);

        // Step 2: Fund the contract with ETH so it has something to withdraw
        deal(TARGET, 10 ether);

        // Step 3: Record attacker's initial balance
        uint256 initialBalance = attacker.balance;

        // Step 4: Call withdrawStuckETH() as owner
        // We need to impersonate the attacker address since that's now the owner
        vm.prank(attacker);
        FoundationToken_Comprehensive_Smart_Contract_Audit target = FoundationToken_Comprehensive_Smart_Contract_Audit(TARGET);
        target.withdrawStuckETH();

        // Step 5: Verify attacker's balance increased
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
